// GOW-Port: the deko3d builds of the GS renderer's shaders (Switch, docs/switch.md "deko3d renderer").
// The table is generated by tools/dk_shaders.py (uam, GLSL -> DKSH) into gs_dk_shaders_gen.cpp; gs_dk.cpp looks a
// shader up by the FNV-1a 64 hash of the exact source text the GL backend passes to glShaderSource.
#pragma once

#include <cstdint>

namespace GSDK
{
    // std140 member of a family's GSU block; type indexes kTypeNames (float vec2 vec3 vec4 int ivec2 ivec3 ivec4 uint
    // uvec2 uvec3 uvec4)
    struct UniformInfo
    {
        const char *name;
        uint32_t offset;
        uint32_t type;
    };
    // programs sharing one GSU layout and sampler numbering (draw, shuffle, present, clut, pack, scale)
    struct Family
    {
        const char *name;
        const UniformInfo *uniforms; // ends with name == nullptr
        const char *const *samplers; // binding = index; ends with nullptr
        uint32_t uboSize;
    };
    struct ShaderBinary
    {
        uint64_t hash;   // FNV-1a 64 of the GL source; the converter's own shaders use small fixed ids
        uint32_t stage;  // 0 vertex, 1 fragment, 2 compute
        uint32_t family; // index into kFamilies
        const unsigned char *code; // DKSH: control section, then the code
        uint32_t size;
    };
    // fixed ids of the presentation scaler (tools/dk_shaders.py SCALE_*), not GL sources
    constexpr uint64_t kScaleVertexId = 1u, kScaleFragmentId = 2u;

    extern const Family kFamilies[];
    extern const ShaderBinary kShaders[];
    extern const unsigned kShaderCount;
    extern const char *const kTypeNames[];
}
